ENTIDAD = "Municipalidad de Villa El Salvador"

DEFECTO = {
    "entidad": ENTIDAD,
    "titulo": "Verificación de carnet de sanidad",
    "pie": "Los datos mostrados deben coincidir con el carnet físico.",
    "marca_opacidad": 12,
    "marca_tamano": 70,
    "marca_posicion": 50,
    "marca_carnet": False,
    "carnet_entidad": "MUNICIPALIDAD DISTRITAL DE VILLA EL SALVADOR",
}

def cargar_ajustes():
    a = dict(DEFECTO)
    if AJUSTES_ARCHIVO.exists():
        with open(AJUSTES_ARCHIVO, encoding="utf-8") as f:
            a.update(json.load(f))
    return a

def guardar_ajustes(a):
    with open(AJUSTES_ARCHIVO, "w", encoding="utf-8") as fh:
        json.dump(a, fh, ensure_ascii=False, indent=2)

def cargar_usuarios():
    if not USUARIOS_ARCHIVO.exists():
        default = {"admin": {"clave": generate_password_hash("admin123"), "ajustes": True, "usuarios": True}}
        with open(USUARIOS_ARCHIVO, "w", encoding="utf-8") as f:
            json.dump(default, f)
        return default
        
    with open(USUARIOS_ARCHIVO, encoding="utf-8") as f:
        data = json.load(f)
        
    migrado = False
    for k, v in list(data.items()):
        if isinstance(v, str): 
            data[k] = {"clave": v, "ajustes": (k == "admin"), "usuarios": (k == "admin")}
            migrado = True
            
    if "admin" not in data:
        data["admin"] = {"clave": generate_password_hash("admin123"), "ajustes": True, "usuarios": True}
        migrado = True
        
    if migrado:
        guardar_usuarios(data)
        
    return data

def guardar_usuarios(usuarios):
    if "admin" in usuarios:
        usuarios["admin"]["ajustes"] = True
        usuarios["admin"]["usuarios"] = True
        
    with open(USUARIOS_ARCHIVO, "w", encoding="utf-8") as f:
        json.dump(usuarios, f)

def vista(plantilla, **kw):
    return render_template_string(plantilla, a=cargar_ajustes(), logo=LOGO.exists(), **kw)

