def ver_capeco(codigo):
    codigo = codigo.upper()
    r = cargar_capeco().get(codigo)
    logo_src = url_for("capeco_logo_img") if CAPECO_LOGO.exists() else CAPECO_LOGO_DEFECTO
    banner_src = url_for("capeco_banner_img") if CAPECO_BANNER.exists() else CAPECO_BANNER_DEFECTO
    if not r:
        return vista(CAPECO_PUBLICA, c=None, codigo=codigo, logo_capeco=logo_src, banner_capeco=banner_src, programas_capeco=CAPECO_PROGRAMAS_DEFECTO), 404
    return vista(CAPECO_PUBLICA, c=type("C", (), r), codigo=codigo, logo_capeco=logo_src, banner_capeco=banner_src, programas_capeco=CAPECO_PROGRAMAS_DEFECTO)

@app.route("/v/<codigo>/certificado.pdf")
def capeco_pdf_publico(codigo):
    from PIL import Image
    codigo = codigo.upper()
    r = cargar_capeco().get(codigo)
    if not r:
        abort(404)
    hoja1 = dibujar_capeco_hoja1(codigo, r, f"{base_publica()}/v/{codigo}")
    buf = io.BytesIO()
    if CAPECO_HOJA2.exists():
        hoja2 = Image.open(CAPECO_HOJA2).convert("RGB")
        hoja1.save(buf, format="PDF", resolution=150.0, save_all=True, append_images=[hoja2])
    else:
        hoja1.save(buf, format="PDF", resolution=150.0)
    return Response(buf.getvalue(), mimetype="application/pdf",
                    headers={"Content-Disposition": f"attachment; filename=certificado_capeco_{codigo}.pdf"})

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000, debug=True)
